function clamp01(v){return Math.max(0,Math.min(1,Number(v||0)))}function computeCentroidDistance(qCentroids,dbCentroids){const n=qCentroids.length;if(n===0)return 0;let sumDist=0;for(let i=0;i<n;i++){const q=qCentroids[i];const d=dbCentroids[i];const dx=Number(q?.x||0)-Number(d?.x||0);const dy=Number(q?.y||0)-Number(d?.y||0);sumDist+=Math.hypot(dx,dy)}return sumDist/n}export function computeHoleSimilarity(queryHoles,dbHoles){const qCount=Number(queryHoles?.hole_count??(Array.isArray(queryHoles?.hole_centroids)?queryHoles.hole_centroids.length:0));const dbCount=Number(dbHoles?.hole_count??(Array.isArray(dbHoles?.hole_centroids)?dbHoles.hole_centroids.length:0));const diff=Math.abs(qCount-dbCount);if(diff>=1){return Math.max(0,1-.5*diff)}if(qCount===0&&dbCount===0){return 1}const qArr=Array.isArray(queryHoles?.hole_centroids)?[...queryHoles.hole_centroids]:[];const dbArr=Array.isArray(dbHoles?.hole_centroids)?[...dbHoles.hole_centroids]:[];if(qArr.length===0||dbArr.length===0||qArr.length!==dbArr.length){return.85}qArr.sort((a,b)=>Number(a.x||0)-Number(b.x||0));dbArr.sort((a,b)=>Number(a.x||0)-Number(b.x||0));const distDirect=computeCentroidDistance(qArr,dbArr);const qMirrored=qArr.map(p=>({...p,x:1-Number(p.x||0)})).sort((a,b)=>a.x-b.x);const distMirror=computeCentroidDistance(qMirrored,dbArr);const bestDist=Math.min(distDirect,distMirror);return clamp01(1-bestDist)}export function computeAspectRatioSimilarity(qAR,dbAR){const a=Math.max(.01,Number(qAR||1));const b=Math.max(.01,Number(dbAR||1));const diff=Math.abs(a-b);const maxAR=Math.max(a,b);return clamp01(1-diff/maxAR)}export function scoreCandidateGeometry(candidate,queryGeometry,weights={wVec:.45,wHoles:.4,wRatio:.15}){const sVec=clamp01(candidate?.vector_similarity??candidate?.similarity??0);if(!queryGeometry||queryGeometry.hole_count===undefined){return{final_score:sVec,s_vec:sVec,s_holes:1,s_ratio:1,geometric_warning:null}}const sHoles=computeHoleSimilarity(queryGeometry,{hole_count:candidate?.hole_count??0,hole_centroids:candidate?.hole_centroids??[]});const sRatio=computeAspectRatioSimilarity(queryGeometry?.aspect_ratio??1,candidate?.aspect_ratio??1);const finalScore=Number((weights.wVec*sVec+weights.wHoles*sHoles+weights.wRatio*sRatio).toFixed(4));let warning=null;const qCount=Number(queryGeometry.hole_count||0);const dbCount=Number(candidate?.hole_count||0);if(sVec>.85&&qCount!==dbCount){warning=`Kiểu dáng giống (${Math.round(sVec*100)}%) nhưng khác số lỗ: Ảnh chụp có ${qCount} lỗ, catalogue có ${dbCount} lỗ.`}return{final_score:finalScore,s_vec:sVec,s_holes:Number(sHoles.toFixed(4)),s_ratio:Number(sRatio.toFixed(4)),geometric_warning:warning}}export function rerankCandidatesByGeometry(candidates,queryGeometry,options={}){const list=Array.isArray(candidates)?[...candidates]:[];if(!list.length)return[];const scored=list.map(c=>{const geo=scoreCandidateGeometry(c,queryGeometry,options.weights);return{...c,geometric_score:geo.final_score,s_vec:geo.s_vec,s_holes:geo.s_holes,s_ratio:geo.s_ratio,geometric_warning:geo.geometric_warning}});scored.sort((a,b)=>b.geometric_score-a.geometric_score);return scored}